{
  "prose": [
    {
      "key": "headline",
      "text": "Keep {arm:September}. Both candidates increase cost and degrade character adherence."
    },
    {
      "key": "lede",
      "text": "{arm:September} delivers the highest adherence at {pass_rate.September|pct} while costing {cost_per_1k.September|usd} compared to over {cost_per_1k.1017|usd} for both alternatives. A switch would require a candidate that reduces spend without regressing persona adherence."
    },
    {
      "key": "confidence.caveats.late:aspect",
      "text": "The primary aspect character adherence (v2) was set on {late_criteria.aspect.set_at}; material only if other dimensions were disregarded."
    },
    {
      "key": "confidence.caveats.late:control",
      "text": "The control {arm:September} was designated on {late_criteria.control.set_at}; material only if a different baseline was intended."
    },
    {
      "key": "confidence.caveats.judge_uncalibrated",
      "text": "The judge model {judge.model} has insufficient calibration; material only if comparative grading between arms is systematic rather than random."
    },
    {
      "key": "decision.recommendation",
      "text": "Retain {arm:September} in production. It maintains {pass_rate.September|pct} pass rate at {cost_per_1k.September|usd}."
    },
    {
      "key": "decision.why_not",
      "text": "{arm:1017} drops adherence by {reading.1017.change|abs|pts} points while increasing cost to {cost_per_1k.1017|usd}. {arm:qwen3.8-flash} drops adherence by {reading.qwen3.8-flash.change|abs|pts} points ({reading.qwen3.8-flash.interval|interval} points) and raises cost to {cost_per_1k.qwen3.8-flash|usd}."
    },
    {
      "key": "decision.watch",
      "text": "The weakest margin is {weakest.arm} with {weakest.value|pts} points against {weakest.threshold|pts} points on {weakest.criterion} ({weakest.margin} points gap). Note reasoning ratio differed across models ({reasoning_ratio.September|pct} on {arm:September} vs {reasoning_ratio.1017|pct} on {arm:1017}), and {arm:qwen3.8-flash} had two degraded harness runs. Prior insight that {arm:qwen3.8-flash} lowers production costs is contradicted."
    },
    {
      "key": "decision.next",
      "text": "Test lighter prompt variants or lower reasoning budgets on {arm:September} to reduce cost without sacrificing persona adherence."
    },
    {
      "key": "summary.0.title",
      "text": "Production Replicating Cost"
    },
    {
      "key": "summary.1.title",
      "text": "Persona Holds Character Rate"
    },
    {
      "key": "sections.readings_spine.eyebrow",
      "text": "Character Adherence"
    },
    {
      "key": "sections.readings_spine.headline",
      "text": "Both candidates hold within the declared margin but degrade pass rates"
    },
    {
      "key": "sections.readings_spine.takeaway",
      "text": "Points show difference from {arm:September} with intervals against the {aspect.margin|int} point margin."
    },
    {
      "key": "sections.readings_spine.title",
      "text": ""
    },
    {
      "key": "sections.readings_spine.caption",
      "text": "Evaluated on {aspect.name} at {cases} cases."
    },
    {
      "key": "sections.strata_diffs.eyebrow",
      "text": "Stratum Breakdown"
    },
    {
      "key": "sections.strata_diffs.headline",
      "text": "Character drops concentrate in off lane and multi-turn conversations"
    },
    {
      "key": "sections.strata_diffs.takeaway",
      "text": "Bars display percentage point drop compared to {arm:September} across strata."
    },
    {
      "key": "sections.strata_diffs.title",
      "text": ""
    },
    {
      "key": "sections.strata_diffs.caption",
      "text": "Stratum differences are uncorrected descriptive slices."
    },
    {
      "key": "sections.failure_examples.eyebrow",
      "text": "Failure Cases"
    },
    {
      "key": "sections.failure_examples.headline",
      "text": "Failures stem from out-of-lane direct advice and system explanations"
    },
    {
      "key": "sections.failure_examples.takeaway",
      "text": "Representative transcripts flagged as non-adherent by the judge."
    },
    {
      "key": "sections.failure_examples.title",
      "text": ""
    },
    {
      "key": "sections.failure_examples.caption",
      "text": "Showing sample failure excerpts from off lane and machinery strata."
    },
    {
      "key": "durable_claims.0",
      "text": "Both {arm:qwen3.8-flash} and {arm:1017} regressed production replicating cost by {contrast.qwen3.8-flash.production_replicating_cost.delta|usd} and {contrast.1017.production_replicating_cost.delta|usd} per conversation."
    },
    {
      "key": "durable_claims.1",
      "text": "Both {arm:qwen3.8-flash} and {arm:1017} regressed persona holds character by {contrast.qwen3.8-flash.persona.holds_character.delta|pts} points and {contrast.1017.persona.holds_character.delta|pts} points."
    },
    {
      "key": "method.0.term",
      "text": "Design & Depth"
    },
    {
      "key": "method.0.text",
      "text": "{cases} cases evaluated with {repeats} repeats per case."
    },
    {
      "key": "method.1.term",
      "text": "Evaluation Criteria"
    },
    {
      "key": "method.1.text",
      "text": "Aspect {aspect.name} with non-inferiority margin of {aspect.margin|pts} points."
    },
    {
      "key": "method.2.term",
      "text": "Statistical Multiplicity"
    },
    {
      "key": "method.2.text",
      "text": "{family.family_size} contrasts corrected via {family.correction} at alpha {family.alpha}."
    },
    {
      "key": "method.3.term",
      "text": "Latency Comparison"
    },
    {
      "key": "method.3.text",
      "text": "{caveats.latency}"
    },
    {
      "key": "method.4.term",
      "text": "Simulator Settings"
    },
    {
      "key": "method.4.text",
      "text": "Simulator sent settings were unrecorded across runs and could introduce confounding."
    },
    {
      "key": "method.5.term",
      "text": "Unreported Telemetry"
    },
    {
      "key": "method.5.text",
      "text": "Input tokens, LLM calls, and output tokens were not captured in this run."
    },
    {
      "key": "explore.title",
      "text": "Margin Sensitivity"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the margin does not flip the decision because {arm:September} dominates both candidates on cost and character adherence; {arm:qwen3.8-flash} breaks margin below {flip_margin.qwen3.8-flash|pts} points and {arm:1017} below {flip_margin.1017|pts} points."
    },
    {
      "key": "explore.controls.margin_slider.title",
      "text": "Non-inferiority margin (pts)"
    }
  ]
}

